 "overall_summary": "The candidate immediately jumps into listing features, user roles, and metrics without establishing the context, the core customer needs, or the rationale behind moving upmarket to enterprise retailers.",
 "strengths": [
  "Identified a specific percentage-point increase in invoices paid on time as a primary metric.",
  "Mentioned user roles such as organization leaders and accountants."
 ],
 "weaknesses": [
  {
   "tag": "no_clear_problem_framing",
   "evidence": "The candidate starts proposing a solution and success metrics right after hearing the question without asking or stating who the customer is, what the goal is, or what is in scope.",
   "fix": "Spend the first minute defining the problem by stating assumptions about enterprise merchants, goals, and constraints out loud before diving into features or metrics."
  }
 ],
 "next_steps": [
  "Practice structuring product strategy questions by starting with problem clarification and goal alignment.",
  "Explicitly define target user segments within the enterprise space before discussing specific use cases or workflows."
 ]
}

